(function(){try{var e=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},s=new e.Error().stack;s&&(e._sentryDebugIds=e._sentryDebugIds||{},e._sentryDebugIds[s]="09168ebd-9810-4544-a802-2ecfdfbff47b",e._sentryDebugIdIdentifier="sentry-dbid-09168ebd-9810-4544-a802-2ecfdfbff47b")}catch{}})();var t="Code de conduite de la communauté",n={p1:"Nous aimons tous la musique ! Comme toute communauté, nous avons un code de conduite pour préserver l’harmonie et la bonne ambiance, et pour que chacun se sente à l’aise ici. Construisons ensemble un espace bienveillant qui nous inspire à créer."},r={p1:"Principes de coexistence :",p2:"Respect",p3:"Convivialité",p4:"Équité"},u={p1:"Comportement attendu :",p2:"Traitez tous les membres avec respect.",p3:"Les commentaires constructifs sont les bienvenus.",p5:"Traitez les autres comme vous aimeriez qu’on vous traite.",p4:"Tout tourne autour de la musique ; veillons à ce que nos commentaires et nos contenus ne portent que sur la musique."},o={p1:"Comportements inacceptables (nous pouvons supprimer votre compte sans avertissement) :",p3:"Spam.",p4:"Partage de contenu à caractère sexuel.",p5:"Publier des commentaires visant à dénigrer, offenser ou importuner un membre de la communauté.",p2:"Traiter les créateurs de manière irrespectueuse ou offensante."},a={p2:"Partager du contenu à caractère sexuel, quelle qu’en soit la nature (images, commentaires, etc.).",p4:"Envoyer du spam aux autres membres.",p1:"Motifs entraînant un bannissement immédiat :",p3:"Partager du contenu ou faire des commentaires qui encouragent la violence, le racisme, la xénophobie, l’homophobie, le sexisme, etc."},i={p1:"D’autres comportements inacceptables :",p2:"Insulter ou publier des commentaires humiliants à l’égard de tout membre de la communauté :",p4:"Deuxième fois : nous désactiverons définitivement la possibilité de commenter ou nous supprimerons votre compte.",p5:"Spam auprès de l’assistance :",p3:"1re fois : nous désactiverons la possibilité de publier des commentaires jusqu’à nouvel ordre.",p6:"Notre équipe d’assistance sera toujours heureuse de vous aider, à condition que vous nous écriviez avec respect et exclusivement au sujet de notre plateforme. Les comportements irrespectueux ou assimilables à du spam ne sont pas les bienvenus et peuvent entraîner la suppression de votre compte."},p={p1:"Qu'est-ce qu'un commentaire irrespectueux ?",p2:"Ce type de commentaire est généralement hors sujet, inapproprié, préjudiciable ou tout simplement agaçant. Son auteur ne l’écrit pas avec bienveillance et vise à faire en sorte que l’autre personne se sente mal, voire à l’humilier.",p3:"Si vous n’êtes pas sûr que votre commentaire soit respectueux, évitez de le publier et trouvez une manière respectueuse et civilisée de vous exprimer."},m={p1:"Actions publiques :"},l={title:t,s1:n,s2:r,s3:u,s4:o,s6:a,s7:i,s8:p,s5:m};export{l as default,n as s1,r as s2,u as s3,o as s4,m as s5,a as s6,i as s7,p as s8,t as title};

